// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        address caller = makeAddr("caller");
        vm.deal(caller, amount);
        vm.prank(caller);
        c.deposit{value: amount}();
        uint256 ethBefore = caller.balance;
        vm.prank(caller);
        c.withdraw(amount);
        uint256 ethAfter = caller.balance;
        assertTrue(ethAfter == ethBefore + amount);
    }
}
